def load_flashcards() -> list[dict]:
    return [dict(card) for card in _FLASHCARDS]


def filter_by_category(cards, category) -> list[dict]:
    return [dict(card) for card in cards if card.get('category') == category]


def get_categories(cards) -> list[str]:
    return sorted({str(card.get('category')) for card in cards if card.get('category')})
